"use client";
import { useActionState } from "react";
import { createCommercialCode } from "@/app/ops/commercial/actions";
import { CopyLink } from "@/components/copy-link";

export function CommercialCodeForm() {
  const [state, action, pending] = useActionState(createCommercialCode, { error: "", token: "", kind: "" });
  return <><form action={action} className="commercial-create-form"><label>Access type<select name="kind"><option value="demo">Private demo link</option><option value="tester">Complimentary workspace code</option></select></label><label>Label<input name="label" required minLength={2} maxLength={100} placeholder="Co-founder / investor introduction"/></label><label>Workspace plan<select name="plan"><option value="sme">SME, 25 people</option><option value="startup">Startup, 5 people</option><option value="enterprise">Enterprise, 100 people</option></select></label><label>Code valid for (days)<input name="expiryDays" type="number" min={1} max={365} defaultValue={30} required/></label><label>Tester access duration (days)<input name="accessDays" type="number" min={1} max={365} defaultValue={90} required/></label><label>Maximum uses<input name="maxUses" type="number" min={1} max={100} defaultValue={5} required/></label><button className="btn btn-primary" disabled={pending}>{pending ? "Creating…" : "Create access"}</button></form><p className="muted">Demo uses count browser sessions, which last up to 8 hours. Tester uses count distinct workspaces. Tester duration begins on redemption; demo access always ends at the code expiry.</p>{state.error && <p className="notice" role="alert">{state.error}</p>}{state.token && <div className="notice" role="status"><strong>Created. Keep this code somewhere secure; it is shown only now.</strong><div className="commercial-secret"><code>{state.token}</code><CopyLink value={state.token}/></div>{state.kind === "demo" && <div className="commercial-secret"><a href={`https://demo.fielded.ai/access#${state.token}`} target="_blank" rel="noreferrer">Open private demo link</a><CopyLink value={`https://demo.fielded.ai/access#${state.token}`}/></div>}</div>}</>;
}
